// Obtener la fecha del formulario (campo Fecha de Fillout)
const preguntas = $input.first().json.body.submission.questions;
const campoFecha = preguntas.find(q => q.id === "o1P9");

let fecha;
if (campoFecha && campoFecha.value) {
  // Usar la fecha del formulario
  fecha = new Date(campoFecha.value);
} else {
  // Si no hay fecha en el formulario, usar fecha actual Bogotá
  fecha = new Date();
  fecha.setHours(fecha.getHours() - 5);
}

// Generar nombre de carpeta del mes: YYYY-MM
const mes = fecha.toISOString().substring(0, 7); // ej: "2026-04"

// Pasar al siguiente nodo
return [{
  json: {
    ...$input.first().json,
    carpeta_mes: mes
  }
}];

