// Leer output del AI Data Processor
let raw = $('AI Data Processor').first().json.output || '';
raw = raw.replace(/```json/g, '').replace(/```/g, '').trim();
const formData = JSON.parse(raw);

// Leer todas las filas de Sheets para obtener último SRV
const sheetsData = $('Read Servicios Sheets').all();
const ids = sheetsData
  .map(item => item.json.id_servicio)
  .filter(id => id && id.startsWith('SRV-'))
  .map(id => parseInt(id.replace('SRV-', '')))
  .filter(n => !isNaN(n));

const lastSRV = ids.length > 0 ? Math.max(...ids) : 0;
const nextSRV = 'SRV-' + String(lastSRV + 1).padStart(3, '0');

return [{
  json: {
    ...formData,
    id_servicio: nextSRV
  }
}];

// Leer todos los clientes existentes
const clientes = $('Read Clientes Sheet').all();

// Encontrar el CLI más alto
const ids = clientes
  .map(item => item.json.id_cliente)
  .filter(id => id && id.startsWith('CLI-'))
  .map(id => parseInt(id.replace('CLI-', '')))
  .filter(n => !isNaN(n));

const lastCLI = ids.length > 0 ? Math.max(...ids) : 0;
const nextCLI = 'CLI-' + String(lastCLI + 1).padStart(3, '0');

// Datos del formulario
const data = $('Generate IDs').first().json;

return [{
  json: {
    ...data,
    id_cliente: nextCLI,
    nombre_cliente: data.nombre_cliente_nuevo
  }
}];

const data = $('Generate IDs').first().json;
const clientesSheet = $('Read Clientes Sheet').all();
// Buscar cliente por NIT
const clienteEncontrado = clientesSheet.find(
  row => String(row.json.nit_cedula) === String(data.nit_cedula)
);
// Datos del cliente
let idCliente, nombreCliente;
if (clienteEncontrado) {
  idCliente = clienteEncontrado.json.id_cliente;
  nombreCliente = clienteEncontrado.json.nombre;
} else {
  try {
    idCliente = $('Generate CLI Code').first().json.id_cliente;
    nombreCliente = data.nombre_cliente_nuevo;
  } catch(e) {
    idCliente = 'CLI-000';
    nombreCliente = data.nombre_cliente_nuevo;
  }
}
const sucursal = data.tipo_cliente === 'Cliente existente'
  ? (data.sucursal_existente || '')
  : (data.sucursal_nuevo || '');
return [{
  json: {
    id_servicio: data.id_servicio,
    fecha: data.fecha,
    hora_inicio: data.hora_inicio,
    hora_fin: data.hora_fin,
    tecnico: data.tecnico,
    solicitud_servicio: data.solicitud_servicio,
    id_cliente: idCliente,
    nombre_cliente: nombreCliente,
    nit_cedula: data.nit_cedula,
    telefono: data.telefono,
    correo_cliente: data.correo_cliente,
    direccion: data.direccion,
    sucursal: sucursal,
    contacto: data.contacto || '',
    equipos_intervenidos: data.equipos_intervenidos,
    trabajos_realizados: data.trabajos_realizados,
    observaciones: data.observaciones,
    repuestos_suministros: data.repuestos_suministros,
    correo_envio: data.correo_cliente
  }
}];

const item = $input.first();
return [{
  json: {
    ...item.json,
    raw_content: JSON.stringify(item.json.body)
  }
}];

